contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool doPause) public payable {
        require(address(this).balance >= 0);

        bool pausedAfterPause;
        bool depositWhilePausedReverted;
        bool pausedAfterUnpause;
        bool depositAfterUnpauseReverted;

        if (doPause) {
            try c.pause() { } catch { }
            pausedAfterPause = c.paused();

            try c.deposit(DepositParams({token: address(0), amount: 1, to: address(this)})) {
                depositWhilePausedReverted = false;
            } catch {
                depositWhilePausedReverted = true;
            }

            try c.unpause() { } catch { }
            pausedAfterUnpause = c.paused();

            try c.deposit(DepositParams({token: address(0), amount: 1, to: address(this)})) {
                depositAfterUnpauseReverted = false;
            } catch {
                depositAfterUnpauseReverted = true;
            }

            assert(!pausedAfterPause || depositWhilePausedReverted);
            assert(pausedAfterUnpause || !depositAfterUnpauseReverted);
        } else {
            bool pausedInitially = c.paused();
            assert(!pausedInitially);
        }
    }

    receive() external payable { }
}

