contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address collateralToken,
        address borrowToken,
        uint256 depositCollateralAmount,
        uint256 depositBorrowAmount,
        uint256 creditAmountIn,
        uint256 tenor,
        uint256 lenderLoanAmount
    ) public payable {
        // Whitelist: only operate when the protocol is initialized with known tokens.
        InitializeDataParams memory d = InitializeDataParams({
            weth: address(0),
            underlyingCollateralToken: collateralToken,
            underlyingBorrowToken: borrowToken,
            variablePool: address(0)
        });
        // (d is unused; calls below only go through c's public surface.)

        // Provide an offer and deposit so a borrow can be created.
        uint256[] memory tenors = new uint256[](1);
        tenors[0] = tenor;
        int256[] memory aprs = new int256[](1);
        aprs[0] = 0.05e18;
        uint256[] memory mult = new uint256[](1);
        mult[0] = 1e18;

        YieldCurve memory curve;
        curve.tenors = tenors;
        curve.aprs = aprs;
        curve.marketRateMultipliers = mult;

        SellCreditLimitParams memory lim;
        lim.curveRelativeTime = curve;
        c.sellCreditLimit{value: 0}(lim);

        c.deposit{value: 0}(DepositParams({token: collateralToken, amount: depositCollateralAmount, to: address(this)}));
        c.deposit{value: 0}(DepositParams({token: borrowToken, amount: depositBorrowAmount, to: address(this)}));

        uint256 borrowBefore = c.getUserView(address(this)).borrowATokenBalance;
        uint256 collateralBefore = c.getUserView(address(this)).collateralTokenBalance;
        uint256 debtBefore = c.getUserView(address(this)).debtBalance;

        SellCreditMarketParams memory p;
        p.lender = address(this);
        p.creditPositionId = type(uint256).max;
        p.amount = creditAmountIn;
        p.tenor = tenor;
        p.deadline = block.timestamp + 1 days;
        p.maxAPR = type(uint256).max;
        p.exactAmountIn = true;

        bool reverted;
        uint256 cashAmountOut;
        try c.sellCreditMarket{value: 0}(p) returns (uint256 out) {
            cashAmountOut = out;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // If it succeeded, cash must not exceed credit, and state must be consistent.
            uint256 borrowAfter = c.getUserView(address(this)).borrowATokenBalance;
            uint256 debtAfter = c.getUserView(address(this)).debtBalance;
            assert(debtAfter >= debtBefore);
            assert(cashAmountOut <= creditAmountIn);
        } else {
            // On revert, state must be unchanged.
            uint256 borrowAfter = c.getUserView(address(this)).borrowATokenBalance;
            uint256 collateralAfter = c.getUserView(address(this)).collateralTokenBalance;
            uint256 debtAfter = c.getUserView(address(this)).debtBalance;
            assert(borrowAfter == borrowBefore);
            assert(collateralAfter == collateralBefore);
            assert(debtAfter == debtBefore);
        }
    }

    receive() external payable {}
}

